import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const n="/llamatron/assets/articulate_editor.MOIQ7ZMp.svg",g=JSON.parse('{"title":"Articulate","description":"","frontmatter":{},"headers":[],"relativePath":"generators/ARTICULATE.md","filePath":"generators/ARTICULATE.md"}'),o={name:"generators/ARTICULATE.md"};function i(c,e,h,l,p,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="articulate" tabindex="-1">Articulate <a class="header-anchor" href="#articulate" aria-label="Permalink to &quot;Articulate&quot;">​</a></h1><p>Articulate scales how long each note sounds, compared with what the pattern writes. Shorter leaves a gap before the next note; longer holds a note over a rest after it, but never past where the next note starts or past the clip&#39;s end. Articulate is one of the three shapes, each a percentage that ramps from a start to an end, which <a href="./../GENERATORS#shapes">Generators</a> describes: where each is set, which wins, and the settings they share. The Articulate percentage runs from 10% to 200%.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+n+'" alt="An Articulate generator&#39;s settings"></p><p>The settings are those every shape shares, which <a href="./../GENERATORS#shapes">Generators</a> describes.</p><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Set Articulate in the <code>+ Articulate</code> section of a Scene page or a clip page, or make a Articulate generator and add it to a chain, as <code>articulate: name</code>, to paint one shape on many clips and change it in one place. <code>examples/learning/15_acid_articulate.yml</code> takes an acid house line from blips to slurs.</p>',7)])])}const A=t(o,[["render",i]]);export{g as __pageData,A as default};
